1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest case ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums per main item type (each + fee) ---
16	  it.todo("a sword → premium 100 G base + 10 G first insurance + 5 G fee = 115 G");
17	  it.todo("an amulet → premium 60 G base + 6 G first insurance + 5 G fee = 71 G");
18	  it.todo("a staff → premium 80 G base + 8 G first insurance + 5 G fee = 93 G");
19	  it.todo("a potion → premium 40 G base + 4 G first insurance + 5 G fee = 45 G");
20	
21	  // --- Components and building blocks ---
22	  it.todo("2 runes → 50 G base premium");
23	  it.todo("3 runes → 60 G base premium (block applies)");
24	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
25	  it.todo("7 runes → 175 G base premium");
26	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
27	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
28	
29	  // --- Item-scoped modifiers ---
30	  it.todo("cursed sword adds a 50 % surcharge on the sword's base premium");
31	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (+30 %)");
32	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
33	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");
34	
35	  // --- Modifier scope on multi-item policies ---
36	  it.todo(
37	    "cursed sword + plain amulet → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
38	  );
39	
40	  // --- Policy-scoped modifiers ---
41	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
42	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
43	  it.todo("first insurance adds a 10 % surcharge on the policy base premium");
44	  it.todo("second contract of a customer → 15 % follow-up discount applies");
45	
46	  // --- Rounding ---
47	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
48	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
49	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
50	
51	  // --- Integration examples ---
52	  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
53	  it.todo(
54	    "long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G",
55	  );
56	
57	  // --- Claim processing: standard reimbursement ---
58	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
59	  it.todo("rune (insurance value 250 G), damage 200 G → payout 100 G");
60	
61	  // --- Claim processing: special clauses ---
62	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
63	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
64	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
65	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
66	
67	  // --- Deductible per damage event ---
68	  it.todo(
69	    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
70	  );
71	
72	  // --- Insurance sum and cap ---
73	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
74	  it.todo("policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
75	  it.todo("policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only), cap 3500 G");
76	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
77	
78	  // --- Cap exhaustion across successive claims ---
79	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
80	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
81	
82	  // --- Multiple items of the same type ---
83	  it.todo(
84	    "two swords insured, dragon attack damages both → each damage entry is a separate damage with its own deductible",
85	  );
86	  it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
87	
88	  // --- Error cases ---
89	  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
90	  it.todo("claim references a damage entry whose item is not part of the policy → error");
91	  it.todo("claim references a damage entry with an unknown item type → error");
92	  it.todo("claim contains a damage entry with amount: -200 → error");
93	});
